31	    /**
32	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
33	     */
34	    default String displayName(Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
39	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
40	        return lastName + ", " + firstName;
41	    }
42	
43	    /**
44	     * Returns the upper-cased first letters of firstName and lastName,
45	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
46	     */
47	    default String initials(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        StringBuilder sb = new StringBuilder();
52	        String firstName = owner.getFirstName();
53	        String lastName = owner.getLastName();
54	        if (firstName != null && !firstName.isEmpty()) {
55	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
56	        }
57	        if (lastName != null && !lastName.isEmpty()) {
58	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
59	        }
60	        return sb.toString();
61	    }
62	
63	    /**
64	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
65	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
66	     * Returns {@code null} unless both the customer code and registration date are present.
67	     */
68	    default String membershipNumber(Owner owner) {
69	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
70	            return null;
71	        }
72	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
73	        return owner.getCustomerCode() + "-M" + yy;
74	    }
75	
76	    /**
77	     * Returns the owner's membership tier: {@code 'SILVER'} when the owner has no
78	     * namesakes (namesakeCount is 0) and an email address is present; otherwise
79	     * {@code 'BRONZE'}.
80	     */
81	    default String membershipTier(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        Integer namesakeCount = owner.getNamesakeCount();
86	        String email = owner.getEmail();
87	        boolean noNamesakes = namesakeCount != null && namesakeCount == 0;
88	        boolean hasEmail = email != null && !email.isEmpty();
89	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
90	    }
91	
92	    /** Fixed city-to-region table used to derive an owner's locality. */
93	    Map<String, String> CITY_REGION = Map.of(
94	        "Sydney", "NSW",
95	        "Melbourne", "VIC",
96	        "Brisbane", "QLD");
97	
98	    /**
99	     * Derives the owner's locality (region) from the city using the fixed city-to-region
100	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
101	     * Returns {@code "UNKNOWN"} when the city is {@code null} or not in the table.
102	     */
103	    default String locality(Owner owner) {
104	        if (owner == null) {
105	            return null;
106	        }
107	        String city = owner.getCity();
108	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
109	    }
